import { REGION_TEMPLATES } from './realm-content-v18.js';
const inheritedLaw={permitted:'permitted',regulated:'licensed',forbidden:'forbidden'};
export function publicMagicAt(s,id){const p=s.world.locations.find(p=>p.id===id),r=s.realm?.sites[id]?.regionId;return s.realm?.lawVersion===0?inheritedLaw[p?.necromancyLaw]||'licensed':REGION_TEMPLATES.find(t=>t.id===r)?.law.publicMagic||inheritedLaw[p?.necromancyLaw]||'licensed';}
export function currentPlaceDescription(s,p){if(!p)return '';let text=p.description||'';for(const old of ['Willing ancestral rites and the study of the dead are permitted; coercion and grave theft remain crimes.','Ancestral rites require a witness or academy license; raising bodies and binding unwilling souls are prohibited.','Public necromantic practice is prohibited. Authorities require a witness or evidence before opening an investigation.'])text=text.replace(old,'');text=text.replace(/ Current public magic law: [^.]+\./g,'').trim();return text+` Current public magic law: ${publicMagicAt(s,p.id)}. A local witness or evidence is still required.`;}
